def load(path):
    return json.loads(path.read_text(encoding="utf-8"))


def save(path, data):
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def enrich_pages():
    data = load(PAGES)
    seen = set()
    for page in data:
        title = page.get("title")
        if title in PAGE_REPLACEMENTS:
            page["content"] = MARKER + PAGE_REPLACEMENTS[title]
            seen.add(title)
    missing = set(PAGE_REPLACEMENTS) - seen
    if missing:
        raise RuntimeError(f"Páginas não encontradas: {sorted(missing)}")
    save(PAGES, data)


def enrich_posts():
    data = load(POSTS)
    seen = set()
    for post in data:
        title = post.get("title")
        if title in POST_ADDITIONS:
            base = post.get("content", "")
            if MARKER in base:
                base = base.split(MARKER, 1)[0]
            post["content"] = base + MARKER + POST_ADDITIONS[title]
            seen.add(title)
    missing = set(POST_ADDITIONS) - seen
    if missing:
        raise RuntimeError(f"Posts não encontrados: {sorted(missing)}")
    save(POSTS, data)


def upgrade_publisher():
    text = PUBLISHER.read_text(encoding="utf-8")
    if "import re\n" not in text:
        text = text.replace("import os\n", "import os\nimport re\n", 1)
    if "POST_URL_PATTERN" not in text:
        anchor = "def normalized_labels(labels):\n"
        helper = '''POST_URL_PATTERN = re.compile(r"\\{\\{POST_URL\\|(.+?)\\}\\}")\n\ndef resolve_post_urls(content: str, url_by_title: dict) -> str:\n    def repl(match):\n        title = match.group(1).strip().casefold()\n        return html.escape(url_by_title.get(title, \"#\"), quote=True)\n    return POST_URL_PATTERN.sub(repl, content)\n\n\n'''
        text = text.replace(anchor, helper + anchor, 1)
    old = "    by_title = {item.get(\"title\", \"\").strip().casefold(): item for item in existing}\n\n    for post in posts:\n        title = post[\"title\"].strip()\n        rendered_content = render_post_content(post, blog_name)\n"
    new = "    by_title = {item.get(\"title\", \"\").strip().casefold(): item for item in existing}\n    url_by_title = {key: item.get(\"url\", \"#\") for key, item in by_title.items()}\n\n    for post in posts:\n        title = post[\"title\"].strip()\n        rendered_content = resolve_post_urls(render_post_content(post, blog_name), url_by_title)\n"
    if old in text:
        text = text.replace(old, new, 1)
    elif "resolve_post_urls(render_post_content" not in text:
        raise RuntimeError("Não foi possível atualizar links internos no publicador")
    PUBLISHER.write_text(text, encoding="utf-8")


def main():
    enrich_pages()
    enrich_posts()
    upgrade_publisher()
    print("Conteúdo institucional e artigos enriquecidos para SEO/AdSense.")


if __name__ == "__main__":
    main()
